let saved=[];try{saved=JSON.parse(localStorage.getItem('blue-basket-saved')||'[]');if(!Array.isArray(saved))saved=[]}catch{}saved=saved.filter(id=>items.some(x=>x.id===id));
const header=`<div class="announcement">A PERSONAL COLLECTION OF IDEAS <span>✦</span> 한국경제 AI 교육 포트폴리오</div><header class="header"><a class="brand" href="index.html" aria-label="eunda works 홈"><span class="brand-star" aria-hidden="true">✧</span>eunda works<span class="brand-period">.</span></a><nav class="nav" aria-label="주 메뉴">${routes.map(([id,name])=>`<a href="${id}.html" ${page===id?'class="active" aria-current="page"':''}>${name}</a>`).join('')}</nav><button class="saved" id="show-saved" aria-label="관심 작품 보기">♡ <span>My picks</span><b id="saved-count">${saved.length}</b></button></header>`;
const footer=`<section class="intro-strip"><h2>좋아하는 것을 담고, 가능성을 발견해요.</h2><p>커머스의 시선으로 발견한 AI의 가능성.<br>한국경제 AI 교육에서 시작된 작은 실험들을 담습니다.</p></section><footer class="footer"><a href="index.html"><strong>eunda works.</strong></a><span>© 2026 eunda works. A collection of curiosities.</span><span>Made with curiosity & AI ✦</span></footer><dialog id="detail"><button class="close" aria-label="닫기">×</button><div class="modal-body"></div></dialog>`;
const typeArt='<div class="type-art"><small>NOTES & DISCOVERIES</small>Ideas<br><i>to go.</i><hr><em>A fresh perspective on AI.</em></div>';
const home=`<section class="hero"><div class="hero-inner wrap"><div class="hero-copy"><div class="eyebrow">CREATIVE ARCHIVE / VOL. 2026</div><h1>eunda<br><span class="serif">works</span><span class="title-star" aria-hidden="true">✧</span></h1><p>작은 호기심이 반짝이는 작업이 되기까지.<br>커머스의 시선으로 모은 AI 크리에이티브 아카이브.</p><a class="pill" href="#collections">컬렉션 둘러보기 <span>↗</span></a></div><div class="hero-art"><img src="${heroImage}" alt="파스텔 하늘 위로 떠 있는 투명한 유리 별과 작은 구슬"><div class="round-sticker">a little curiosity,<strong>a little magic.</strong></div><span class="art-caption">DAYDREAM STUDY — NO. 001</span></div></div></section><div class="ticker"><span>CURATED WITH CURIOSITY</span><i>✦</i><span>POWERED BY AI</span><i>✦</i><span>MADE FOR COMMERCE</span><i>✦</i><span>ALWAYS EXPLORING</span></div><section class="collection wrap" id="collections"><div class="section-top"><div><h2>Collected with <span class="serif">curiosity.</span></h2><p>지금, 어떤 영감을 담아볼까요?</p></div><span class="sample-label">04 COLLECTIONS · SAMPLE WORKS</span></div><div class="category-grid">${routes.map(([id,name,eng],i)=>`<a class="category-card" href="${id}.html"><div class="category-visual ${id}"><span class="cat-no">NO. 0${i+1}</span>${id==='artcle'?typeArt:id==='final'?'<div class="type-final">THE<br>FINAL<br><i>EDIT.</i><small>IDEAS INTO IMPACT</small></div>':`<img src="${heroImage}" alt="${id==='image'?'별빛과 파스텔 이미지 컬렉션':'브랜드 필름 키 비주얼'}" style="${id==='video'?'object-position:70% center':''}">${id==='video'?'<span class="play-disc">▷</span>':''}`}</div><div class="category-title"><h3>${name}</h3><span>↗</span></div><p>${eng} — ${['생각을 읽는 시간','취향을 발견하는 장면','움직임으로 전하는 이야기','배움이 하나의 프로젝트로'][i]}</p></a>`).join('')}</div></section>`;
document.getElementById('app').innerHTML=header+(page==='home'?home:'<main class="wrap" id="page-content"></main>')+footer;
const heart=id=>`<button class="heart" data-save="${id}" aria-label="${items.find(x=>x.id===id).title} 관심 작품 저장" aria-pressed="${saved.includes(id)}">${saved.includes(id)?'♥':'♡'}</button>`;
function heading(eng,ko,desc,count){return `<section class="page-heading"><div class="eyebrow">HOME / ${eng}</div><div class="head-row"><div><h1>${ko}</h1><p>${desc}</p></div><span class="item-count">${count} ITEMS · CURATED BY ME</span></div></section>`}
function card(x){return `<article class="product" data-tag="${x.tag}">${heart(x.id)}<button class="product-open" data-open="${x.id}"><div class="product-picture"><img src="${x.image}" alt="${x.title}" style="object-position:${x.position||'center'};${x.id==='i2'?'transform:scale(1.45)':x.id==='i3'?'transform:scale(1.2)':''}"><span class="badge">${x.type==='video'?'STORYBOARD':'AI GENERATED'}</span>${x.type==='video'?'<span class="play-disc">▷</span><span class="duration">영상 기획안</span>':''}</div><div class="product-meta">${x.tag.toUpperCase()} / 2026</div><h3>${x.title}</h3><p class="product-desc">${x.desc}</p></button></article>`}
function renderPage(){const target=document.getElementById('page-content');if(!target)return;
if(page==='artcle'){const a=items.filter(x=>x.type===page);target.innerHTML=heading('THE EDITORIAL / READING ROOM','Notes <span class="serif">& daydreams.</span>','커머스와 AI 사이, 새로운 관점과 작은 발견을 기록합니다.','03')+`<section class="editorial-feature"><div class="feature-art">${typeArt}</div><div><div class="eyebrow">EDITOR’S PICK · SAMPLE ARTICLE</div><h2>${a[0].title}</h2><p>고객은 더 이상 상품명만 검색하지 않습니다.<br>나의 취향을 이해하는 AI는 쇼핑의 순간을 어떻게 바꿀까요?</p><button class="pill" data-open="a1">기사 읽어보기 <span>↗</span></button></div></section><div class="section-top"><h2>Latest stories</h2><span class="sample-label">생각을 담은 세 편의 글</span></div><section class="article-list">${a.map((x,i)=>`<article class="article-row"><span>0${i+1}</span><div><button data-open="${x.id}"><h3>${x.title}</h3></button><p>${x.tag} · ${x.desc}</p></div><button data-open="${x.id}">읽어보기 ↗</button>${heart(x.id)}</article>`).join('')}</section>`;}
if(page==='image'){target.innerHTML=heading('VISUAL DIARY / IMAGE STUDIO','Little pieces of <span class="serif">wonder.</span>','상상 속 아이디어를 꺼내어, 눈에 보이는 장면으로 만듭니다.','03')+`<div class="toolbar" aria-label="이미지 분류">${['전체','브랜드 비주얼','컬러 스터디'].map((t,i)=>`<button class="filter ${i===0?'active':''}" data-filter="${t}" aria-pressed="${i===0}">${t}</button>`).join('')}</div><section class="products">${items.filter(x=>x.type===page).map(card).join('')}</section>`;}
if(page==='video'){target.innerHTML=heading('MOTION ROOM','Ideas in <span class="serif">motion.</span>','짧은 순간에 전하는 긴 여운. 브랜드의 이야기를 움직임으로 그립니다.','03')+`<section class="cinema"><div class="cinema-copy"><div class="eyebrow">IN THE SPOTLIGHT · STORYBOARD</div><h2>작은 빛이<br>모이는 순간</h2><p>일상의 호기심이 하나의 컬렉션이 되기까지.<br>30초 브랜드 필름의 첫 번째 이야기.</p><button class="pill" data-open="v1">영상 기획안 보기 <span>↗</span></button></div><img src="${heroImage}" alt="브랜드 필름의 파스텔 별빛 키 비주얼"></section><div class="section-top"><h2>The motion shelf</h2><span class="sample-label">영상 업로드 전 · 임시 기획안</span></div><section class="products film">${items.filter(x=>x.type===page).map(card).join('')}</section>`;}
if(page==='final'){target.innerHTML=heading('THE FINAL EDIT','From idea <span class="serif">to impact.</span>','배운 것을 연결하고, 커머스의 다음 가능성을 제안합니다.','01')+`<section class="final-feature"><div class="final-cover"><span>FINAL PROJECT / 2026</span><h2>COMMERCE<br>MEETS<br><i>AI.</i></h2><img src="${heroImage}" alt="AI 커머스 프로젝트의 유리 별 오브젝트"><span>A NEW WAY TO DISCOVER.</span></div><div class="final-details"><div class="eyebrow">CONCEPT PROJECT · 기획 단계</div><h2>취향을 발견하는<br>AI 커머스</h2><p>수많은 상품 속에서 ‘나에게 맞는 것’을 발견하는 경험.<br>AI를 활용한 상품 탐색과 콘텐츠 제작을 하나의 고객 여정으로 연결하는 프로젝트입니다.</p><dl class="specs"><div><dt>교육 과정</dt><dd>한국경제 AI 교육</dd></div><div><dt>프로젝트 유형</dt><dd>개인 프로젝트 · 임시 기획안</dd></div><div><dt>작업 범위</dt><dd>리서치, 콘텐츠 기획, 비주얼 제작</dd></div><div><dt>결과물</dt><dd>기사 · 브랜드 이미지 · 영상 기획</dd></div></dl><button class="pill" data-open="f1">프로젝트 자세히 보기 <span>↗</span></button></div></section><div class="section-top"><h2>Behind the project</h2></div><section class="process"><article><span>01</span><h3>Discover · 문제를 발견하다</h3><p>고객의 탐색 과정과 콘텐츠 제작 흐름에서 반복되는 불편을 찾아봅니다.</p></article><article><span>02</span><h3>Make · 아이디어를 실험하다</h3><p>하나의 콘셉트를 기사, 이미지, 영상으로 확장하며 AI와 함께 제작합니다.</p></article><article><span>03</span><h3>Connect · 경험을 연결하다</h3><p>각 결과물을 고객 여정에 연결하고, 더 나은 쇼핑 경험을 제안합니다.</p></article></section>`;}}
renderPage();
const dialog=document.getElementById('detail');const modal=dialog.querySelector('.modal-body');
function openItem(id){const x=items.find(x=>x.id===id);if(!x)return;modal.innerHTML=`<div class="eyebrow">${x.tag}</div><h2>${x.title}</h2>${x.image?`<img src="${x.image}" alt="${x.title}">`:''}<p>${x.body}</p><p class="sample-note">${x.type==='video'?'임시 영상 기획안입니다. 실제 영상은 아직 업로드되지 않았습니다.':x.type==='image'?'포트폴리오 구성을 위한 AI 생성 이미지와 임시 프로젝트 설명입니다.':'포트폴리오 구성을 위한 임시 콘텐츠입니다.'}</p>`;if(!dialog.open)dialog.showModal();}
function showSaved(){modal.innerHTML='<div class="eyebrow">YOUR LITTLE COLLECTION</div><h2>My picks</h2>'+(!saved.length?'<p class="empty">아직 담은 작품이 없어요.<br>컬렉션에서 마음에 드는 작품의 ♡를 눌러보세요.</p>':saved.map(id=>{const x=items.find(x=>x.id===id);return `<div class="saved-row"><button data-open="${id}">${x.title} ↗</button><button data-remove="${id}" aria-label="${x.title} 저장 취소">삭제</button></div>`}).join(''))+'<p class="sample-note">관심 작품은 이 브라우저에 저장됩니다.</p>';if(!dialog.open)dialog.showModal();}
function toggleSave(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];try{localStorage.setItem('blue-basket-saved',JSON.stringify(saved))}catch{}document.getElementById('saved-count').textContent=saved.length;document.querySelectorAll('[data-save]').forEach(b=>{const active=saved.includes(b.dataset.save);b.setAttribute('aria-pressed',active);b.textContent=active?'♥':'♡'});}
document.addEventListener('click',e=>{const open=e.target.closest('[data-open]');if(open)openItem(open.dataset.open);const save=e.target.closest('[data-save]');if(save)toggleSave(save.dataset.save);const remove=e.target.closest('[data-remove]');if(remove){toggleSave(remove.dataset.remove);showSaved()}const filter=e.target.closest('[data-filter]');if(filter){document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===filter);b.setAttribute('aria-pressed',b===filter)});document.querySelectorAll('[data-tag]').forEach(x=>x.classList.toggle('hidden',filter.dataset.filter!=='전체'&&x.dataset.tag!==filter.dataset.filter))}});
document.getElementById('show-saved').addEventListener('click',showSaved);dialog.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});

if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const registrations=[{name:'list_portfolio_projects',description:'Read the portfolio projects and which ones are saved in this browser.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){return items.map(({id,title,type})=>({id,title,type,saved:saved.includes(id)}))}},{name:'set_saved_project',description:'Save or remove a portfolio project in this browser and update the visible My picks count.',inputSchema:{type:'object',properties:{id:{type:'string'},saved:{type:'boolean'}},required:['id','saved'],additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input.saved!=='boolean'||!items.some(x=>x.id===input.id))throw new Error('A valid project id and boolean saved value are required.');if(saved.includes(input.id)!==input.saved)toggleSave(input.id);return {id:input.id,saved:saved.includes(input.id),count:saved.length};}}];
 for(const tool of registrations){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
